<script setup lang="ts">import { ref } from 'vue'; import { useRoute } from 'vue-router'; import RideFallback from '../components/RideFallback.vue'; import { createApiClient } from '../api/client'; const route=useRoute(); const api=createApiClient(); const plate=ref(''); const model=ref(''); const color=ref(''); const saved=ref(false); const error=ref(''); const busy=ref(false); async function save(){if(!plate.value.trim()){return}; busy.value=true; error.value=''; try { await api.updateVehicle(String(route.params.id),{plate:plate.value.trim(),model:model.value.trim()||undefined,color:color.value.trim()||undefined}); saved.value=true } catch { error.value='车辆信息保存失败，请重试' } finally { busy.value=false }} async function openRide(){busy.value=true; error.value=''; try { await api.openRide(String(route.params.id),'manual'); } catch { error.value='叫车准备失败，请重试' } finally { busy.value=false }}</script>
<template><main class="page"><div class="eyebrow">出行准备</div><h1>车辆信息</h1><div v-if="error" class="form-error" role="alert">{{error}}</div><div class="detail-card"><p>请先阅读：同路行不提供司机端、实时定位或自动行车守护。车辆信息仅用于同行识别。</p><label>车牌号<input v-model="plate" required placeholder="粤A·12345" /></label><label>车型（可选）<input v-model="model" placeholder="如：轿车" /></label><label>颜色（可选）<input v-model="color" placeholder="如：白色" /></label><button class="primary-button" :disabled="busy || !plate.trim()" @click="save">{{saved?'已保存':'保存车辆信息'}}</button><button class="secondary-button" :disabled="busy || !saved" @click="openRide">准备叫车</button></div><RideFallback text="请在聊天中确认上车点后复制行程信息" /></main></template>
